using System; using System.Net.Http; using System.Threading; using System.Threading.Tasks; class MyHandler : DelegatingHandler { protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage request, CancellationToken cancellationToken) { Console.WriteLine("Inside Handler, IsAbsolute: " + request.RequestUri.IsAbsoluteUri); return Task.FromResult(new HttpResponseMessage()); } } class Program { static async Task Main() { var client = new HttpClient(new MyHandler()) { BaseAddress = new Uri("http://localhost/") }; var req = new HttpRequestMessage(HttpMethod.Get, "api/auth/login"); await client.SendAsync(req); } }
